1	import { useEffect, useState } from "react";
2	import { prefersReducedMotion } from "../mascot/mascotStore";
3	import { onboardingPhotos } from "./onboardingMedia";
4	
5	const QUERY = "lumen";
6	const TYPE_MS = 110;
7	const TYPE_START_MS = 700;
8	const FOUND_DELAY_MS = 280;
9	
10	const LINES = [
11	  ["2 × galão", "3.40"],
12	  ["1 × pastel de nata", "1.30"],
13	  ["1 × água", "0.90"],
14	] as const;
15	
16	/**
17	 * The "It reads your pictures, too." demo: one word typed into search, and the
18	 * receipt photo that mentions it coming into focus with the match marked.
19	 * Plays once per visit; reduced motion lands on the finished frame.
20	 */
21	export function ReadsPictures() {
22	  const [reduced] = useState(prefersReducedMotion);
23	  const [typed, setTyped] = useState(reduced ? QUERY.length : 0);
24	  const [found, setFound] = useState(reduced);
25	
26	  useEffect(() => {
27	    if (found) return;
28	    if (typed >= QUERY.length) {
29	      const timer = window.setTimeout(() => setFound(true), FOUND_DELAY_MS);
30	      return () => window.clearTimeout(timer);
31	    }
32	    const timer = window.setTimeout(
33	      () => setTyped((count) => count + 1),
34	      typed === 0 ? TYPE_START_MS : TYPE_MS,
35	    );
36	    return () => window.clearTimeout(timer);
37	  }, [found, typed]);
38	
39	  return (
40	    <div className={`reads-pictures${found ? " is-found" : ""}`} aria-hidden="true">
41	      <img
42	        className="reads-backdrop"
43	        src={onboardingPhotos.car}
44	        alt=""
45	        draggable={false}
46	        style={{ left: -10, top: 170 }}
47	      />
48	      <img
49	        className="reads-backdrop"
50	        src={onboardingPhotos.book}
51	        alt=""
52	        draggable={false}
53	        style={{ left: 318, top: 200 }}
54	      />
55	      <div className="reads-search">
56	        <span className="reads-eyes">
57	          <span />
58	          <span />
59	        </span>
60	        <span className="reads-query">{QUERY.slice(0, typed)}</span>
61	        <span className="reads-caret" />
62	      </div>
63	      <div className="reads-receipt">
64	        <span className="reads-receipt-kicker">— RECEIPT —</span>
65	        <span className="reads-receipt-name">
66	          <span className="reads-receipt-mark" />
67	          CAFÉ LUMEN
68	        </span>
69	        <span className="reads-receipt-kicker">Rua das Flores 28, Lisboa</span>
70	        <span className="reads-receipt-rule" />
71	        {LINES.map(([item, price]) => (
72	          <span key={item} className="reads-receipt-line">
73	            <span>{item}</span>
74	            <span>{price}</span>
75	          </span>
76	        ))}
77	        <span className="reads-receipt-rule" />
78	        <span className="reads-receipt-line is-total">
79	          <span>TOTAL</span>
80	          <span>€5.60</span>
81	        </span>
82	        <span className="reads-receipt-kicker is-footer">14 MAR 2026 · 09:12</span>
83	        <span className="reads-receipt-kicker">obrigado!</span>
84	      </div>
85	    </div>
86	  );
87	}
