16	// how long one cell takes to separate, in progress units
17	const MORPH = 0.055;
18	const SAMPLE = 128;
19	const COLOR_MS = 420;
20	const GUTTER_FROM = 0.35;
21	const GUTTER_TO = 0.75;
22	const PHOTO_FROM = 0.93;
