24	type Cell = {
25	  x: number;
26	  y: number;
27	  w: number;
28	  h: number;
29	  r: number;
30	  g: number;
31	  b: number;
32	  tone: number;
33	  detail: number;
34	  splitAt: number;
35	  parent: Cell | null;
36	  kids: [Cell, Cell] | null;
37	};
38	
39	type Sums = { n: number; r: number; g: number; b: number; l: number; l2: number };
40	
41	type Patch = {
42	  x: number;
43	  y: number;
44	  w: number;
45	  h: number;
46	  r: number;
47	  g: number;
48	  b: number;
49	  tone: number;
50	};
