52	type Scene = {
53	  ctx: CanvasRenderingContext2D;
54	  root: Cell;
55	  width: number;
56	  height: number;
57	  scale: number;
58	  clock: number;
59	  split: number;
60	  fade: number;
61	  hasColors: boolean;
