65	// written as comparisons so NaN falls through to 0
66	const clamp01 = (n: number) => (n > 0 ? (n < 1 ? n : 1) : 0);
67	const mix = (a: number, b: number, t: number) => a + (b - a) * t;
68	const easeOut = (t: number) => 1 - (1 - t) ** 3;
69	
70	function smoothstep(a: number, b: number, x: number) {
71	  const t = clamp01((x - a) / (b - a));
72	  return t * t * (3 - 2 * t);
73	}
74	
75	// never reaches its ceiling, so a run that outlasts the estimate keeps creeping
76	function selfPaced(elapsedMs: number, durationMs: number) {
77	  return HOLD * (1 - Math.exp(-elapsedMs / (durationMs > 0 ? durationMs : 1)));
78	}
