85	function makeCell(x: number, y: number, w: number, h: number, parent: Cell | null): Cell {
86	  return {
87	    x,
88	    y,
89	    w,
90	    h,
91	    r: 0,
92	    g: 0,
93	    b: 0,
94	    tone: hash(x + 3.1, y + 1.7, w * 31.7),
95	    detail: 0,
96	    splitAt: 0,
97	    parent,
98	    kids: null,
99	  };
100	}
