102	// splitting the biggest cell each time keeps cells square and the count rising one at a time
103	function buildTree(aspect: number) {
104	  const root = makeCell(0, 0, 1, 1, null);
105	  const leaves: Cell[] = [root];
106	  const branches: Cell[] = [];
107	
108	  while (leaves.length < CELLS) {
109	    let pick = 0;
110	    let widest = -1;
111	    for (let i = 0; i < leaves.length; i++) {
112	      const c = leaves[i];
113	      // the jitter only breaks ties between cells of equal size
114	      const area = c.w * aspect * c.h * (1 + 0.12 * hash(c.x, c.y, 7.3));
115	      if (area > widest) {
116	        widest = area;
117	        pick = i;
118	      }
119	    }
120	
121	    const parent = leaves.splice(pick, 1)[0];
122	    const wide = parent.w * aspect >= parent.h;
123	    const half = wide ? parent.w / 2 : parent.h / 2;
124	    const a = wide
125	      ? makeCell(parent.x, parent.y, half, parent.h, parent)
126	      : makeCell(parent.x, parent.y, parent.w, half, parent);
127	    const b = wide
128	      ? makeCell(parent.x + half, parent.y, half, parent.h, parent)
129	      : makeCell(parent.x, parent.y + half, parent.w, half, parent);
