131	    parent.kids = [a, b];
132	    branches.push(parent);
133	    leaves.push(a, b);
134	  }
135	
136	  const opening = OPENING_CELLS - 1;
137	  const rest = Math.max(1, branches.length - opening);
138	  // the opening splits sit before zero so those cells are already apart on frame one
139	  branches.forEach((cell, i) => {
140	    cell.splitAt = i < opening ? -MORPH : (LAST_SPLIT * (i - opening + 1)) / rest;
