152	      const b = gather(cell.kids[1]);
153	      s = { n: a.n + b.n, r: a.r + b.r, g: a.g + b.g, b: a.b + b.b, l: a.l + b.l, l2: a.l2 + b.l2 };
154	    } else {
155	      s = { n: 0, r: 0, g: 0, b: 0, l: 0, l2: 0 };
156	      const x0 = Math.round(cell.x * size);
157	      const y0 = Math.round(cell.y * size);
158	      const x1 = Math.max(x0 + 1, Math.round((cell.x + cell.w) * size));
159	      const y1 = Math.max(y0 + 1, Math.round((cell.y + cell.h) * size));
160	      for (let y = y0; y < y1; y++) {
161	        for (let x = x0; x < x1; x++) {
162	          const i = (y * size + x) * 4;
163	          const r = pixels[i];
164	          const g = pixels[i + 1];
165	          const b = pixels[i + 2];
166	          const l = 0.299 * r + 0.587 * g + 0.114 * b;
167	          s.n++;
168	          s.r += r;
169	          s.g += g;
170	          s.b += b;
171	          s.l += l;
172	          s.l2 += l * l;
173	        }
174	      }
175	    }
176	    const n = s.n || 1;
177	    cell.r = s.r / n;
178	    cell.g = s.g / n;
179	    cell.b = s.b / n;
180	    cell.detail = Math.max(0, s.l2 / n - (s.l / n) * (s.l / n));
181	    return s;
182	  };
183	  gather(root);
184	}
185	
186	// reuse the same time slots so only the order changes and the pacing stays identical
187	function orderByDetail(branches: Cell[], openedBefore: number) {
188	  const pending = branches.filter((c) => c.splitAt > openedBefore);
189	  if (pending.length < 2) return;
190	
191	  const slots = pending.map((c) => c.splitAt).sort((a, b) => a - b);
192	  const queue = pending.filter((c) => !c.parent || c.parent.splitAt <= openedBefore);
193	
194	  let next = 0;
195	  while (queue.length && next < slots.length) {
196	    let pick = 0;
197	    for (let i = 1; i < queue.length; i++) {
198	      if (queue[i].detail > queue[pick].detail) pick = i;
199	    }
200	    const cell = queue.splice(pick, 1)[0];
201	    cell.splitAt = slots[next++];
202	    for (const kid of cell.kids ?? []) {
203	      if (kid.kids) queue.push(kid);
204	    }
205	  }
206	}
207	
208	function coverRect(iw: number, ih: number, w: number, h: number) {
209	  const s = Math.max(w / iw, h / ih);
210	  return { dx: (w - iw * s) / 2, dy: (h - ih * s) / 2, dw: iw * s, dh: ih * s };
211	}
212	
213	function greyOf(tone: number, clock: number) {
214	  return 30 + tone * 13 + Math.sin(clock * 1.5 + tone * 6.28) * 3;
215	}
216	
217	function drawScene(s: Scene) {
218	  const { ctx, root, width, height, split } = s;
219	  // without pixel access the grid stays grey, but the photo still fades in below
220	  const tint = s.hasColors ? s.fade : 0;
221	  const shade = (grey: number, target: number) => Math.round(mix(grey, target, tint));
222	  const base = greyOf(root.tone, s.clock);
223	
224	  // gutters recess into this instead of cutting through to the surface behind
225	  ctx.fillStyle = `rgb(${Math.round(shade(base, root.r) * 0.92)},${Math.round(
226	    shade(base, root.g) * 0.92,
227	  )},${Math.round(shade(base, root.b) * 0.92)})`;
228	  ctx.fillRect(0, 0, width, height);
229	
230	  const soft = 1 - smoothstep(GUTTER_FROM, GUTTER_TO, split);
231	  const gutter = s.scale * soft;
232	  const rounded = soft > 0.01 && typeof ctx.roundRect === "function";
233	
234	  const paint = (p: Patch) => {
235	    // snap to whole pixels so neighbouring cells stay flush with no seam
236	    const x = Math.round(p.x);
237	    const y = Math.round(p.y);
238	    const w = Math.round(p.x + p.w) - x;
239	    const h = Math.round(p.y + p.h) - y;
240	
241	    const onLeft = x <= 0;
242	    const onTop = y <= 0;
243	    const onRight = x + w >= width;
244	    const onBottom = y + h >= height;
245	
246	    // only interior edges get a gutter, so the outer silhouette stays the frame
247	    const left = onLeft ? 0 : gutter;
248	    const top = onTop ? 0 : gutter;
249	    const innerW = w - left - (onRight ? 0 : gutter);
250	    const innerH = h - top - (onBottom ? 0 : gutter);
251	    if (innerW <= 0 || innerH <= 0) return;
252	
253	    const grey = greyOf(p.tone, s.clock);
254	    ctx.fillStyle = `rgb(${shade(grey, p.r)},${shade(grey, p.g)},${shade(grey, p.b)})`;
255	
256	    if (rounded) {
257	      const radius = Math.min(innerW, innerH) * 0.12 * soft;
258	      ctx.beginPath();
259	      ctx.roundRect(x + left, y + top, innerW, innerH, [
260	        !onLeft && !onTop ? radius : 0,
261	        !onRight && !onTop ? radius : 0,
262	        !onRight && !onBottom ? radius : 0,
263	        !onLeft && !onBottom ? radius : 0,
264	      ]);
265	      ctx.fill();
266	    } else {
267	      ctx.fillRect(x + left, y + top, innerW, innerH);
268	    }
269	  };
270	
271	  const walk = (cell: Cell, p: Patch) => {
272	    if (!cell.kids || split < cell.splitAt) {
273	      paint(p);
274	      return;
275	    }
276	    // children start on the parent's rect and separate into their own
277	    const t = easeOut(clamp01((split - cell.splitAt) / MORPH));
278	    for (const kid of cell.kids) {
279	      walk(kid, {
280	        x: mix(p.x, kid.x * width, t),
281	        y: mix(p.y, kid.y * height, t),
282	        w: mix(p.w, kid.w * width, t),
283	        h: mix(p.h, kid.h * height, t),
284	        r: mix(p.r, kid.r, t),
285	        g: mix(p.g, kid.g, t),
286	        b: mix(p.b, kid.b, t),
287	        tone: mix(p.tone, kid.tone, t),
288	      });
289	    }
290	  };
291	
292	  walk(root, { x: 0, y: 0, w: width, h: height, r: root.r, g: root.g, b: root.b, tone: root.tone });
293	
294	  if (!s.image) return;
295	  const photo = s.hasColors ? smoothstep(PHOTO_FROM, 1, split) * s.fade : s.fade;
296	  if (photo <= 0.002) return;
297	
298	  const fit = coverRect(s.image.naturalWidth, s.image.naturalHeight, width, height);
299	  ctx.globalAlpha = photo;
300	  ctx.drawImage(s.image, fit.dx, fit.dy, fit.dw, fit.dh);
301	  ctx.globalAlpha = 1;
302	}
303	
304	function readAverages(el: HTMLImageElement, root: Cell, branches: Cell[], at: number) {
305	  const buffer = document.createElement("canvas");
306	  buffer.width = SAMPLE;
307	  buffer.height = SAMPLE;
308	  const ctx = buffer.getContext("2d", { willReadFrequently: true });
309	  if (!ctx) return false;
310	
311	  const fit = coverRect(el.naturalWidth, el.naturalHeight, SAMPLE, SAMPLE);
312	  ctx.drawImage(el, fit.dx, fit.dy, fit.dw, fit.dh);
313	
314	  try {
315	    measureTree(root, ctx.getImageData(0, 0, SAMPLE, SAMPLE).data, SAMPLE);
316	    orderByDetail(branches, at);
317	    return true;
318	  } catch {
319	    return false;
320	  }
321	}
322	
323	export function GridReveal({
324	  src,
325	  aspect,
326	  estimatedDuration = 2400,
327	  className,
328	}: {
329	  src: string | null;
330	  /** Width over height of the frame the canvas fills. */
331	  aspect: number;
332	  estimatedDuration?: number;
333	  className?: string;
334	}) {
335	  const frameRef = useRef<HTMLDivElement>(null);
336	  const canvasRef = useRef<HTMLCanvasElement>(null);
337	  const srcRef = useRef(src);
338	  const loadNow = useRef<(() => void) | null>(null);
339	
340	  useEffect(() => {
341	    const canvas = canvasRef.current;
342	    const frame = frameRef.current;
343	    const ctx = canvas?.getContext("2d");
344	    if (!canvas || !frame || !ctx) return;
345	
346	    const reduce = prefersReducedMotion();
347	    const { root, branches } = buildTree(aspect);
348	    const scene: Scene = {
349	      ctx,
350	      root,
351	      width: 0,
352	      height: 0,
353	      scale: 1,
354	      clock: 0,
355	      split: 0,
356	      fade: 0,
357	      hasColors: false,
358	      image: null,
359	    };
360	
361	    let loadedAt = -1;
362	    let cancelled = false;
363	
364	    const render = (split: number, now: number) => {
365	      scene.split = split;
366	      scene.fade = loadedAt < 0 ? 0 : smoothstep(0, COLOR_MS, now - loadedAt);
367	      drawScene(scene);
368	    };
369	
370	    const repaint = () => {
371	      if (!reduce) return render(scene.split, performance.now());
372	      // reduced motion has no loop, so jump straight to the settled frame
373	      const settled = loadedAt < 0 ? performance.now() : loadedAt + COLOR_MS;
374	      render(scene.image ? 1 : WAIT_CAP, settled);
375	    };
376	
377	    const resize = () => {
378	      const dpr = Math.min(window.devicePixelRatio || 1, 2);
379	      const rect = frame.getBoundingClientRect();
380	      const w = Math.max(1, Math.round(rect.width * dpr));
381	      const h = Math.max(1, Math.round(rect.height * dpr));
382	      scene.scale = dpr;
383	      if (w === scene.width && h === scene.height) return;
384	      scene.width = w;
385	      scene.height = h;
386	      canvas.width = w;
387	      canvas.height = h;
388	      // resizing the canvas clears it, so always paint again
389	      repaint();
390	    };
391	
392	    resize();
393	    const observer = new ResizeObserver(resize);
394	    observer.observe(frame);
395	
396	    // The tree outlives `src`, so a photo arriving mid-wait carries on from
397	    // the grid already on screen instead of snapping back to four cells.
398	    let requested: string | null = null;
399	    const load = () => {
400	      const url = srcRef.current;
401	      if (!url || url === requested) return;
402	      requested = url;
403	      const el = new Image();
404	      el.decoding = "async";
405	      el.onload = () => {
406	        if (cancelled || !el.naturalWidth || !el.naturalHeight) return;
407	        scene.image = el;
408	        loadedAt = performance.now();
409	        scene.hasColors = readAverages(el, root, branches, scene.split);
410	        if (reduce) repaint();
411	      };
412	      el.src = url;
413	    };
414	    load();
415	
416	    if (reduce) {
417	      repaint();
418	      loadNow.current = load;
419	      return () => {
420	        cancelled = true;
421	        loadNow.current = null;
422	        observer.disconnect();
423	      };
424	    }
425	
426	    let frameId = 0;
427	    let last = 0;
428	    let elapsed = 0;
429	    let eased = 0;
430	    let split = 0;
431	
432	    const tick = (now: number) => {
433	      frameId = requestAnimationFrame(tick);
434	      if (!last) last = now;
435	      load();
436	      const dt = Math.min((now - last) / 1000, 0.05);
437	      last = now;
438	      elapsed += dt;
439	      scene.clock = elapsed;
440	
441	      const ready = scene.image !== null;
442	      // the image landing is what finishes the run, not the clock
443	      const target = ready ? 1 : selfPaced(elapsed * 1000, estimatedDuration);
444	      eased += (target - eased) * (1 - Math.exp(-dt * 5.5));
445	      const wanted = Math.min(eased, ready ? 1 : WAIT_CAP);
446	      split += (wanted - split) * (1 - Math.exp(-dt * 4));
447	      render(split, now);
448	
449	      // nothing moves after this, so stop burning frames
450	      if (ready && eased > 0.995 && now - loadedAt > COLOR_MS && split > 0.9995) {
451	        render(1, now);
452	        cancelAnimationFrame(frameId);
453	      }
454	    };
455	    frameId = requestAnimationFrame(tick);
456	
457	    return () => {
458	      cancelled = true;
459	      cancelAnimationFrame(frameId);
460	      observer.disconnect();
461	    };
462	  }, [aspect, estimatedDuration]);
463	
464	  // Reduced motion has no loop to notice a new photo, so hand it over directly.
465	  useEffect(() => {
466	    srcRef.current = src;
467	    loadNow.current?.();
468	  }, [src]);
469	
470	  return (
471	    <div ref={frameRef} className={className} aria-hidden="true">
472	      <canvas ref={canvasRef} />
473	    </div>
474	  );
475	}
