import { useEffect, useLayoutEffect, useRef, useState, type CSSProperties } from "react";
import { prefersReducedMotion } from "../mascot/mascotStore";
import { onboardingPhotos } from "./onboardingMedia";

const QUERY = "lumen";

// Timeline in ms from arrival: a beat, the grid of results settles in, "lumen"
// is typed, the receipt rises to the front, the scan beam reads it, then the
// match is marked. Everything is a one-shot.
const TYPE_START_MS = 1500;
const TYPE_MS = 170;
const RAISE_MS = 2650;
const SCAN_START_MS = 3150;
const SCAN_MS = 1500;
const FOUND_MS = SCAN_START_MS + SCAN_MS + 300;
/** How long one line takes to resolve from scrambled glyphs to its words. */
const RESOLVE_MS = 380;
const SCRAMBLE_STEP_MS = 55;

const GLYPHS = "REDACTED#%&";

const LINES = [
  ["2 × galão", "3.40"],
  ["1 × pastel de nata", "1.30"],
  ["1 × água", "0.90"],
] as const;

// Results grid: 4 columns of thumbnails under the search field.
const COLUMNS = 4;
const THUMB_W = 92;
const THUMB_H = 138;
const GAP = 20;
const GRID_TOP = 146;
// The receipt's resting box, and the scale that turns it into a grid thumbnail.
const RECEIPT_W = 220;
const RECEIPT_H = 330;
const RECEIPT_LEFT = 104;
const THUMB_SCALE = THUMB_W / RECEIPT_W;

type Phase = "typing" | "raise" | "scan" | "found";

type Card = {
  key: string;
  /** Typed letters after which this photo no longer matches. */
  drop: number;
  /** Where it slides off to; the car and book stay behind the receipt instead. */
  away: [number, number];
  /** Where it rests behind the receipt after it stops matching. */
  behind?: { x: number; y: number };
};

// Initial order, receipt included, so the grid reads as mixed results.
const ORDER = ["car", "record", "stairs", "book", "vases", "receipt", "sea", "pottery"] as const;
type CardKey = (typeof ORDER)[number];

const CARDS: Record<Exclude<CardKey, "receipt">, Card> = {
  stairs: { key: "stairs", drop: 1, away: [-26, -30] },
  vases: { key: "vases", drop: 1, away: [30, -26] },
  record: { key: "record", drop: 2, away: [-34, 28] },
  sea: { key: "sea", drop: 2, away: [34, 30] },
  pottery: { key: "pottery", drop: 3, away: [0, 36] },
  car: { key: "car", drop: 4, away: [0, 0], behind: { x: -6, y: 170 } },
  book: { key: "book", drop: 5, away: [0, 0], behind: { x: 318, y: 200 } },
};

const BEHIND_SCALE = 1.2;

function slotAt(index: number) {
  return {
    x: (index % COLUMNS) * (THUMB_W + GAP),
    y: GRID_TOP + Math.floor(index / COLUMNS) * (THUMB_H + GAP),
  };
}

/** Deterministic, so a re-render never reshuffles glyphs mid-step. */
function glyphAt(seed: number) {
  const n = Math.sin(seed * 127.1) * 43758.5453;
  return GLYPHS[Math.floor((n - Math.floor(n)) * GLYPHS.length)];
}

function scrambled(text: string, step: number, line: number, keep: number) {
  let out = "";
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    out += i < keep || ch === " " ? ch : glyphAt(step * 131 + line * 17 + i);
  }
  return out;
}

/**
 * The "It reads your pictures, too." demo: "lumen" typed into search, a grid of
 * results narrowing to the receipt photo, a scan beam reading it (the words
 * resolve out of scrambled glyphs as the beam passes), and the match marked.
 * Plays once per visit; reduced motion lands on the finished frame.
 */
export function ReadsPictures() {
  const [reduced] = useState(prefersReducedMotion);
  const [typed, setTyped] = useState(reduced ? QUERY.length : 0);
  const [phase, setPhase] = useState<Phase>(reduced ? "found" : "typing");
  const receiptRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (reduced) return;
    const timers: number[] = [];
    const at = (ms: number, run: () => void) => timers.push(window.setTimeout(run, ms));
    for (let i = 1; i <= QUERY.length; i++) at(TYPE_START_MS + (i - 1) * TYPE_MS, () => setTyped(i));
    at(RAISE_MS, () => setPhase("raise"));
    at(SCAN_START_MS, () => setPhase("scan"));
    at(FOUND_MS, () => setPhase("found"));
    return () => {
      for (const timer of timers) window.clearTimeout(timer);
    };
  }, [reduced]);

  const lines = () =>
    Array.from(receiptRef.current?.querySelectorAll<HTMLElement>("[data-scan]") ?? []);

  // Until the beam reaches a line its words stay unread. Writes into the
  // existing text nodes, so React's tree is left alone.
  useLayoutEffect(() => {
    if (reduced) return;
    const els = lines();
    const finals = els.map((el) => el.textContent ?? "");
    els.forEach((el, i) => {
      if (el.firstChild) el.firstChild.nodeValue = scrambled(finals[i], 0, i, 0);
    });
    return () => {
      els.forEach((el, i) => {
        if (el.firstChild) el.firstChild.nodeValue = finals[i];
      });
    };
  }, [reduced]);

  // The beam's sweep is pure CSS; this resolves each line as the beam reaches
  // it, then stops. One animation frame loop for about two seconds.
  useEffect(() => {
    if (phase !== "scan") return;
    const root = receiptRef.current;
    if (!root) return;
    const box = root.getBoundingClientRect();
    const plan = lines().map((el, i) => {
      const rect = el.getBoundingClientRect();
      const center = (rect.top + rect.height / 2 - box.top) / box.height;
      return { text: el.dataset.scan ?? "", node: el.firstChild, at: center * SCAN_MS, line: i };
    });

    const started = performance.now();
    let frame = 0;
    const tick = (now: number) => {
      const elapsed = now - started;
      let pending = false;
      for (const { text, node, at, line } of plan) {
        if (!node) continue;
        const progress = Math.min(1, Math.max(0, (elapsed - at) / RESOLVE_MS));
        if (progress <= 0) {
          pending = true;
          continue;
        }
        pending ||= progress < 1;
        node.nodeValue =
          progress >= 1
            ? text
            : scrambled(
                text,
                Math.floor(elapsed / SCRAMBLE_STEP_MS),
                line,
                Math.floor(progress * text.length),
              );
      }
      if (pending) frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [phase]);

  const remaining = ORDER.filter((key) => key === "receipt" || typed < CARDS[key].drop);
  // The receipt ranks first once enough of the word is typed.
  const ranked = [...remaining].sort((a, b) => {
    const rank = (key: CardKey) => (key === "receipt" && typed >= 2 ? -1 : ORDER.indexOf(key));
    return rank(a) - rank(b);
  });

  const raised = phase !== "typing";
  const receiptSlot = slotAt(Math.max(0, ranked.indexOf("receipt")));
  const receiptShift = {
    x: receiptSlot.x + THUMB_W / 2 - (RECEIPT_LEFT + RECEIPT_W / 2),
    y: receiptSlot.y + THUMB_H / 2 - (GRID_TOP + RECEIPT_H / 2),
  };

  return (
    <div className={`reads-pictures is-${phase}`} aria-hidden="true">
      {ORDER.map((key, order) => {
        if (key === "receipt") return null;
        const card = CARDS[key];
        const out = typed >= card.drop;
        const slot = slotAt(Math.max(0, ranked.indexOf(key)));
        const spot = out && card.behind ? card.behind : slot;
        return (
          <img
            key={key}
            className={`reads-card${out ? (card.behind ? " is-behind" : " is-out") : ""}`}
            src={onboardingPhotos[key]}
            alt=""
            draggable={false}
            style={
              {
                transform: `translate(${spot.x}px, ${spot.y}px)${
                  out && card.behind ? ` scale(${BEHIND_SCALE})` : ""
                }`,
                "--order": order,
                "--away-x": `${card.away[0]}px`,
                "--away-y": `${card.away[1]}px`,
              } as CSSProperties
            }
          />
        );
      })}
      <div className="reads-search">
        <span className="reads-eyes">
          <span />
          <span />
        </span>
        <span className="reads-query">{QUERY.slice(0, typed)}</span>
        {phase === "found" ? null : <span className="reads-caret" />}
      </div>
      <div
        ref={receiptRef}
        className="reads-receipt"
        style={
          {
            transform: raised
              ? "none"
              : `translate(${receiptShift.x}px, ${receiptShift.y}px) scale(${THUMB_SCALE})`,
            "--order": ORDER.indexOf("receipt"),
          } as CSSProperties
        }
      >
        <span className="reads-beam" />
        <span className="reads-receipt-kicker" data-scan="— RECEIPT —">
