const { app, BrowserWindow } = require("electron");
const fs = require("fs");
const path = require("path");
const url = process.argv[2];
const out = process.argv[3];
fs.mkdirSync(out, { recursive: true });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
app.whenReady().then(async () => {
  const win = new BrowserWindow({ width: 1280, height: 800, show: true, useContentSize: true, webPreferences: { backgroundThrottling: false } });
  await win.loadURL(url);
  await sleep(1500);
  const click = () => win.webContents.executeJavaScript(`(()=>{const b=[...document.querySelectorAll('button')].find(b=>b.textContent.trim()==='Continue'); if(b) b.click(); return !!b;})()`);
  for (let i = 0; i < 3; i++) { await click(); await sleep(i < 2 ? 900 : 0); }
  const t0 = Date.now();
  for (const t of [300, 1000, 1700, 2300, 2900, 3400, 3800, 4200, 4600, 5200, 6500]) {
    const wait = t0 + t - Date.now();
    if (wait > 0) await sleep(wait);
    const img = await win.webContents.capturePage();
    fs.writeFileSync(path.join(out, `t${String(t).padStart(5, "0")}.png`), img.toPNG());
  }
  app.quit();
});
EOF
sleep 4; cat "$TEMP/inkling-reads-dev.log"

