const { app, BrowserWindow } = require("electron");
const fs = require("fs");
const path = require("path");
const url = process.env.SHOT_URL;
const out = process.argv[3];
fs.mkdirSync(out, { recursive: true });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
process.on("unhandledRejection", (e) => {
  fs.writeFileSync(path.join(out, "err.txt"), String((e && e.stack) || e));
  process.exit(4);
});
app.whenReady().then(async () => {
  const win = new BrowserWindow({ width: 1280, height: 800, show: true, useContentSize: true, webPreferences: { backgroundThrottling: false } });
  await win.loadURL(url);
  await sleep(1500);
  const js = (code) => win.webContents.executeJavaScript(code);
  const clickText = (t) =>
    js(`(()=>{const b=[...document.querySelectorAll('button')].find(b=>b.textContent.includes(${JSON.stringify(t)})); if(b) b.click(); return !!b;})()`);
  await clickText("Settings");
  await sleep(700);
  await clickText("Data");
  await sleep(500);
  fs.writeFileSync(path.join(out, "btns.txt"), await js("[...document.querySelectorAll('button')].map(b=>b.textContent.trim()).join('\\n')"));
  await clickText("Show the welcome again");
  await sleep(1500);
  for (let i = 0; i < 3; i++) {
    await clickText("Continue");
    if (i < 2) await sleep(900);
  }
  const t0 = Date.now();
  for (const t of [300, 1000, 1700, 2300, 2900, 3400, 3800, 4200, 4600, 5200, 6500]) {
    const wait = t0 + t - Date.now();
    if (wait > 0) await sleep(wait);
    const img = await win.webContents.capturePage();
    fs.writeFileSync(path.join(out, `t${String(t).padStart(5, "0")}.png`), img.toPNG());
  }
  app.quit();
});

