1	import { useEffect, useLayoutEffect, useRef, useState, type CSSProperties } from "react";
2	import { prefersReducedMotion } from "../mascot/mascotStore";
3	import { onboardingPhotos } from "./onboardingMedia";
4	
5	const QUERY = "lumen";
6	
7	// Timeline in ms from arrival: a beat, the grid of results settles in, "lumen"
8	// is typed, the receipt rises to the front, the scan beam reads it, then the
9	// match is marked. Everything is a one-shot.
10	const TYPE_START_MS = 1500;
11	const TYPE_MS = 170;
12	const RAISE_MS = 2650;
13	const SCAN_START_MS = 3150;
14	const SCAN_MS = 1500;
15	const FOUND_MS = SCAN_START_MS + SCAN_MS + 300;
16	/** How long one line takes to resolve from scrambled glyphs to its words. */
17	const RESOLVE_MS = 380;
18	const SCRAMBLE_STEP_MS = 55;
19	
20	const GLYPHS = "REDACTED#%&";
21	
22	const LINES = [
23	  ["2 × galão", "3.40"],
24	  ["1 × pastel de nata", "1.30"],
25	  ["1 × água", "0.90"],
26	] as const;
27	
28	// Results grid: 4 columns of thumbnails under the search field.
29	const COLUMNS = 4;
30	const THUMB_W = 92;
31	const THUMB_H = 138;
32	const GAP = 20;
33	const GRID_TOP = 146;
34	// The receipt's resting box, and the scale that turns it into a grid thumbnail.
35	const RECEIPT_W = 220;
36	const RECEIPT_H = 330;
37	const RECEIPT_LEFT = 104;
38	const THUMB_SCALE = THUMB_W / RECEIPT_W;
39	
40	type Phase = "typing" | "raise" | "scan" | "found";
41	
42	type Card = {
43	  key: string;
44	  /** Typed letters after which this photo no longer matches. */
45	  drop: number;
46	  /** Where it slides off to; the car and book stay behind the receipt instead. */
47	  away: [number, number];
48	  /** Where it rests behind the receipt after it stops matching. */
49	  behind?: { x: number; y: number };
50	};
51	
52	// Initial order, receipt included, so the grid reads as mixed results.
53	const ORDER = ["car", "record", "stairs", "book", "vases", "receipt", "sea", "pottery"] as const;
54	type CardKey = (typeof ORDER)[number];
55	
56	const CARDS: Record<Exclude<CardKey, "receipt">, Card> = {
57	  stairs: { key: "stairs", drop: 1, away: [-26, -30] },
58	  vases: { key: "vases", drop: 1, away: [30, -26] },
59	  record: { key: "record", drop: 2, away: [-34, 28] },
60	  sea: { key: "sea", drop: 2, away: [34, 30] },
61	  pottery: { key: "pottery", drop: 3, away: [0, 36] },
62	  car: { key: "car", drop: 4, away: [0, 0], behind: { x: -6, y: 170 } },
63	  book: { key: "book", drop: 5, away: [0, 0], behind: { x: 318, y: 200 } },
64	};
65	
66	const BEHIND_SCALE = 1.2;
67	
68	function slotAt(index: number) {
69	  return {
70	    x: (index % COLUMNS) * (THUMB_W + GAP),
71	    y: GRID_TOP + Math.floor(index / COLUMNS) * (THUMB_H + GAP),
72	  };
73	}
74	
75	/** Deterministic, so a re-render never reshuffles glyphs mid-step. */
76	function glyphAt(seed: number) {
77	  const n = Math.sin(seed * 127.1) * 43758.5453;
78	  return GLYPHS[Math.floor((n - Math.floor(n)) * GLYPHS.length)];
79	}
80	
81	function scrambled(text: string, step: number, line: number, keep: number) {
82	  let out = "";
83	  for (let i = 0; i < text.length; i++) {
84	    const ch = text[i];
85	    out += i < keep || ch === " " ? ch : glyphAt(step * 131 + line * 17 + i);
86	  }
87	  return out;
88	}
89	
90	const scanLines = (root: HTMLElement | null) =>
91	  Array.from(root?.querySelectorAll<HTMLElement>("[data-scan]") ?? []);
92	
93	/**
94	 * The "It reads your pictures, too." demo: "lumen" typed into search, a grid of
95	 * results narrowing to the receipt photo, a scan beam reading it (the words
96	 * resolve out of scrambled glyphs as the beam passes), and the match marked.
97	 * Plays once per visit; reduced motion lands on the finished frame.
98	 */
99	export function ReadsPictures() {
100	  const [reduced] = useState(prefersReducedMotion);

99	export function ReadsPictures() {
100	  const [reduced] = useState(prefersReducedMotion);
101	  const [typed, setTyped] = useState(reduced ? QUERY.length : 0);
102	  const [phase, setPhase] = useState<Phase>(reduced ? "found" : "typing");
103	  const receiptRef = useRef<HTMLDivElement>(null);
104	
105	  useEffect(() => {
106	    if (reduced) return;
107	    const timers: number[] = [];
108	    const at = (ms: number, run: () => void) => timers.push(window.setTimeout(run, ms));
109	    for (let i = 1; i <= QUERY.length; i++)
110	      at(TYPE_START_MS + (i - 1) * TYPE_MS, () => setTyped(i));
111	    at(RAISE_MS, () => setPhase("raise"));
112	    at(SCAN_START_MS, () => setPhase("scan"));
113	    at(FOUND_MS, () => setPhase("found"));
114	    return () => {
115	      for (const timer of timers) window.clearTimeout(timer);
116	    };
117	  }, [reduced]);
118	
119	  // Until the beam reaches a line its words stay unread. Writes into the
120	  // existing text nodes, so React's tree is left alone.
121	  useLayoutEffect(() => {
122	    if (reduced) return;
123	    const els = scanLines(receiptRef.current);
124	    const finals = els.map((el) => el.textContent ?? "");
125	    els.forEach((el, i) => {
126	      if (el.firstChild) el.firstChild.nodeValue = scrambled(finals[i], 0, i, 0);
127	    });
128	    return () => {
129	      els.forEach((el, i) => {
130	        if (el.firstChild) el.firstChild.nodeValue = finals[i];
131	      });
132	    };
133	  }, [reduced]);
134	
135	  // The beam's sweep is pure CSS; this resolves each line as the beam reaches
136	  // it, then stops. One animation frame loop for about two seconds.
137	  useEffect(() => {
138	    if (phase !== "scan") return;
139	    const root = receiptRef.current;
140	    if (!root) return;
141	    const box = root.getBoundingClientRect();
142	    const plan = scanLines(root).map((el, i) => {
143	      const rect = el.getBoundingClientRect();
144	      const center = (rect.top + rect.height / 2 - box.top) / box.height;
145	      return { text: el.dataset.scan ?? "", node: el.firstChild, at: center * SCAN_MS, line: i };
146	    });
147	
148	    const started = performance.now();
149	    let frame = 0;
150	    const tick = (now: number) => {
151	      const elapsed = now - started;
152	      let pending = false;
153	      for (const { text, node, at, line } of plan) {
154	        if (!node) continue;
155	        const progress = Math.min(1, Math.max(0, (elapsed - at) / RESOLVE_MS));
